// Pricing rules for the store. This file is locked: read it, don't change it.

// A cart line whose quantity is BULK_THRESHOLD or more is charged at the
// bulk unit price instead of the normal unit price.
const BULK_THRESHOLD = 3;

// A cart holding FREE_SHIPPING_ITEMS or more items total ships free.
// Any smaller cart has SHIPPING_CENTS added to its total.
const FREE_SHIPPING_ITEMS = 5;
const SHIPPING_CENTS = 499;

module.exports = { BULK_THRESHOLD, FREE_SHIPPING_ITEMS, SHIPPING_CENTS };

const { BULK_THRESHOLD, FREE_SHIPPING_ITEMS, SHIPPING_CENTS } = require('./rules');

// Cost of a single cart line, in cents.
function lineTotal(unitCents, bulkCents, quantity) {
  if (quantity > BULK_THRESHOLD) {
    return bulkCents * quantity;
  }
  return unitCents * quantity;
}

// Cost of the whole cart, in cents, including shipping.
// lines is an array of [unitCents, bulkCents, quantity] triples.
function cartTotal(lines) {
  let subtotal = 0;
  let itemCount = 0;
  for (const [unitCents, bulkCents, quantity] of lines) {
    subtotal += lineTotal(unitCents, bulkCents, quantity);
    itemCount += quantity;
  }

  if (itemCount >= FREE_SHIPPING_ITEMS) {
    return subtotal;
  }
  return subtotal + SHIPPING_CENTS;
}

module.exports = { lineTotal, cartTotal };

